import {
  IconRocket,
  IconTable,
  type Icon as TablerIcon,
} from '@tabler/icons-react';

export interface WhatsNewPost {
  slug: string;
  title: string;
  /** e.g. "November 2026" or "Oct 2 – 16, 2026" */
  month: string;
  excerpt: string;
  icon: TablerIcon;
  /**
   * File name of a self-contained HTML post in `public/whats-new-posts/`. When
   * set, the post page shows it in an iframe instead of the placeholder text.
   * Generated by the aura-community-changelog skill.
   */
  embed?: string;
}

/**
 * Newest first. The first entry is the current report and the default page;
 * when a new report is added at the top, the previous ones move down the list.
 */
export const WHATS_NEW_POSTS: WhatsNewPost[] = [
  {
    slug: '2026-10-21',
    title:
      'DataGrid filtering, translatable result counts, and 20 documented components',
    month: 'Oct 17 – 21, 2026',
    excerpt:
      'DataGrid filtering got more flexible, result counts can now be translated, and nine more components have portable docs.',
    icon: IconTable,
    embed: '2026-10-21.html',
  },
  {
    slug: '2026-10-16',
    title: 'Aura 1.0, a stronger DataGrid, and new community charts',
    month: 'Oct 2 – 16, 2026',
    excerpt:
      'Aura reached 1.0, DataGrid gained selection, resizing and loading states, and the community library added a time-series chart, maps and page templates.',
    icon: IconRocket,
    embed: '2026-10-16.html',
  },
];

export function getWhatsNewPostBySlug(slug: string) {
  return WHATS_NEW_POSTS.find((post) => post.slug === slug) ?? null;
}
